import { describe, it, expect } from "vitest";
import type { SceneContext } from "@babylonjs/lite";
import { createOrbitCamera } from "./orbit-camera.ts";

function fakeCanvas() {
    const listeners = new Map<string, Function[]>();
    const attrs = new Set<string>();
    return {
        listeners, tabIndex: -1,
        hasAttribute: (n: string) => attrs.has(n),
        addEventListener(t: string, f: Function) { listeners.set(t, [...(listeners.get(t) ?? []), f]); },
        removeEventListener() {},
        setPointerCapture() {}, releasePointerCapture() {},
        getBoundingClientRect: () => ({ left: 0, top: 0, width: 100, height: 100 }),
        width: 100, height: 100,
    } as any;
}

describe("tmp orbit camera check", () => {
    it("builds camera at radius 10 looking at origin with controls", () => {
        const canvas = fakeCanvas();
        const scene = { _beforeRender: [], meshes: [], lights: [], camera: null } as unknown as SceneContext;
        const cam = createOrbitCamera(canvas, scene);
        expect(cam.radius).toBe(10);
        expect([cam.target.x, cam.target.y, cam.target.z]).toEqual([0, 0, 0]);
        expect(scene.camera).toBe(cam);
        expect(canvas.listeners.get("pointerdown")?.length).toBe(1);
        expect(canvas.listeners.get("wheel")?.length).toBeGreaterThan(0);
        expect(canvas.listeners.get("keydown")?.length).toBe(1);
        expect(canvas.tabIndex).toBe(0);
        // Arrow key drives the camera through the scene's per-frame hook.
        canvas.listeners.get("keydown")[0]({ code: "ArrowLeft", ctrlKey: false, altKey: false, metaKey: false, preventDefault() {} });
        expect((scene as any)._beforeRender.length).toBe(1);
        (scene as any)._beforeRender[0]();
        expect(cam.inertialAlphaOffset).not.toBe(0);
    });
});
